import{_ as t,c as n,o,a3 as a,a9 as r,aa as i,ab as s}from"./chunks/framework.MI-M1z4O.js";const b=JSON.parse(`{"title":"Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process","description":"Technical guide for connecting a remote debugger from IntelliJ IDEA to the V8 Inspector (ws://127.0.0.1:5858) of the SyncETA Electron desktop application's main process and inspecting breakpoints.","frontmatter":{"title":"Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process","description":"Technical guide for connecting a remote debugger from IntelliJ IDEA to the V8 Inspector (ws://127.0.0.1:5858) of the SyncETA Electron desktop application's main process and inspecting breakpoints.","head":[["meta",{"name":"keywords","content":"SyncETA, Electron, IntelliJ IDEA, V8 Inspector, remote debugging, main process, Breakpoint"}],["meta",{"property":"og:title","content":"Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process | Empasy Docs"}],["meta",{"property":"og:description","content":"Step-by-step instructions for launching the Electron main process with dev:debug, connecting via IntelliJ V8 Inspector socket, and debugging with breakpoints."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/logs/20250827_electronDebug"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/logs/20250827_electronDebug"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/logs/20250827_electronDebug"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process | Empasy Docs"}],["meta",{"property":"og:description","content":"Technical guide for connecting a remote debugger from IntelliJ IDEA to the V8 Inspector (ws://127.0.0.1:5858) of the SyncETA Electron desktop application's main process and inspecting breakpoints."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/logs/20250827_electronDebug"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Technical guide for connecting a remote debugger from IntelliJ IDEA to the V8 Inspector (ws://127.0.0.1:5858) of the SyncETA Electron desktop application's main process and inspecting breakpoints."}]],"sort":300},"headers":[],"relativePath":"en/logs/20250827_electronDebug.md","filePath":"en/logs/20250827_electronDebug.md","lastUpdated":1795293539000}`),c={name:"en/logs/20250827_electronDebug.md"};function l(d,e,g,p,h,m){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-to-attaching-an-intellij-idea-remote-debugger-to-the-electron-main-process" tabindex="-1">Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process <a class="header-anchor" href="#guide-to-attaching-an-intellij-idea-remote-debugger-to-the-electron-main-process" aria-label="Permalink to “Guide to Attaching an IntelliJ IDEA Remote Debugger to the Electron Main Process”">​</a></h1><p>The SyncETA desktop application operates on a multi-process architecture consisting of the <strong>Electron Main Process (Node.js / Playwright control)</strong> and the <strong>Renderer Process (Vue 3 UI)</strong>. This document describes the standard procedure for attaching a remote debugger from IntelliJ IDEA to the Electron main process via the V8 Inspector WebSocket (<code>ws://127.0.0.1:5858</code>) and tracing breakpoints.</p><hr><h2 id="_1-launch-in-debug-mode-dev-debug" tabindex="-1">1. Launch in Debug Mode (<code>dev:debug</code>) <a class="header-anchor" href="#_1-launch-in-debug-mode-dev-debug" aria-label="Permalink to “1. Launch in Debug Mode (dev:debug)”">​</a></h2><p>Run the <code>dev:debug</code> script defined in <code>package.json</code> to start the Electron main process with the <code>--inspect=5858</code> flag.</p><p><img src="'+r+'" alt="Launching Debug Mode" loading="lazy"></p><table tabindex="0"><thead><tr><th style="text-align:left;">Script</th><th style="text-align:left;">Internal Flag</th><th style="text-align:left;">Default Debug Port</th></tr></thead><tbody><tr><td style="text-align:left;"><code>yarn dev:debug</code></td><td style="text-align:left;"><code>electron --inspect=5858 .</code></td><td style="text-align:left;"><code>127.0.0.1:5858</code> (V8 Inspector WebSocket)</td></tr></tbody></table><hr><h2 id="_2-connect-to-the-v8-inspector-remote-debugger-socket" tabindex="-1">2. Connect to the V8 Inspector Remote Debugger Socket <a class="header-anchor" href="#_2-connect-to-the-v8-inspector-remote-debugger-socket" aria-label="Permalink to “2. Connect to the V8 Inspector Remote Debugger Socket”">​</a></h2><p><code>Ctrl + Click</code> (or <code>Cmd + Click</code>) the <code>Debugger listening on ws://127.0.0.1:5858/...</code> link printed in the terminal console to immediately attach IntelliJ&#39;s built-in JavaScript/Node.js debugger.</p><p><img src="'+i+'" alt="Opening Debugger" loading="lazy"></p><hr><h2 id="_3-set-breakpoints-and-inspect-runtime-state" tabindex="-1">3. Set Breakpoints and Inspect Runtime State <a class="header-anchor" href="#_3-set-breakpoints-and-inspect-runtime-state" aria-label="Permalink to “3. Set Breakpoints and Inspect Runtime State”">​</a></h2><p>When you set breakpoints in the main process TypeScript source code (such as IPC handlers or Playwright browser context controllers), execution pauses when an event is invoked, allowing you to inspect the Call Stack and local variable states in real time.</p><p><img src="'+s+'" alt="Breakpoint" loading="lazy"></p><hr><h2 id="_4-debugging-targets-and-precautions-by-process" tabindex="-1">4. Debugging Targets and Precautions by Process <a class="header-anchor" href="#_4-debugging-targets-and-precautions-by-process" aria-label="Permalink to “4. Debugging Targets and Precautions by Process”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Process</th><th style="text-align:left;">Execution Runtime</th><th style="text-align:left;">Debugger Attachment Method</th><th style="text-align:left;">Primary Debugging Targets</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Main Process</strong></td><td style="text-align:left;">Node.js / Electron Main</td><td style="text-align:left;"><code>ws://127.0.0.1:5858</code> V8 Inspector socket connection</td><td style="text-align:left;"><code>ipcMain.handle</code>, Playwright browser pool control, local file I/O</td></tr><tr><td style="text-align:left;"><strong>Preload Script</strong></td><td style="text-align:left;">Isolated Context Bridge</td><td style="text-align:left;">Chromium DevTools (<code>Ctrl+Shift+I</code>) Sources tab</td><td style="text-align:left;"><code>contextBridge.exposeInMainWorld</code> API binding verification</td></tr><tr><td style="text-align:left;"><strong>Renderer Process</strong></td><td style="text-align:left;">Chromium / Vue 3</td><td style="text-align:left;">Chromium DevTools or Vite HMR console</td><td style="text-align:left;">Vue 3 component state (Pinia), scenario canvas UI rendering</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Pausing for an extended period at a main process breakpoint may cause IPC response timeouts in the renderer process. When debugging asynchronous IPC calls, it is recommended to temporarily relax timeout thresholds or use conditional breakpoints.</p></div>',19)])])}const y=t(c,[["render",l]]);export{b as __pageData,y as default};
